// Generates synthetic daily attack data and injects it into template.html -> dashboard.html
const fs = require('fs');
const path = require('path');
const dir = __dirname;

let seed = 20261108;
const rnd = () => { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const gauss = () => { let u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };

const types = ['DDoS', 'Phishing', 'Malware', 'Web Defacement', 'Ransomware', 'Kebocoran Data'];
const base = [420, 360, 300, 140, 90, 60];
const growth = [0.35, 0.55, 0.15, -0.10, 0.45, 0.40]; // relative change over the 730 days
const sectors = ['Pemerintah', 'Keuangan', 'Pendidikan', 'Kesehatan', 'Telekomunikasi', 'Lainnya'];
const sw = [0.27, 0.22, 0.16, 0.12, 0.10, 0.13];

const N = 730;
const end = new Date(Date.UTC(2026, 10, 8));
const days = [];
const spikes = types.map(() => ({ at: -1, len: 0, mult: 1 }));
for (let i = 0; i < N; i++) {
  const d = new Date(end.getTime() - (N - 1 - i) * 86400000);
  const dow = d.getUTCDay();
  const weekday = dow === 0 || dow === 6 ? 0.78 : 1.0;
  const vals = types.map((_, k) => {
    if (spikes[k].len <= 0 && rnd() < 0.012) spikes[k] = { len: 2 + Math.floor(rnd() * 4), mult: 1.5 + rnd() * 1.2 };
    const sp = spikes[k].len > 0 ? spikes[k].mult : 1;
    spikes[k].len--;
    const trend = 1 + growth[k] * (i / N);
    const season = 1 + 0.08 * Math.sin((i / 365) * 2 * Math.PI + k);
    return Math.max(1, Math.round(base[k] * trend * season * weekday * sp * (1 + 0.09 * gauss())));
  });
  const total = vals.reduce((a, b) => a + b, 0);
  // split the day's total across sectors; counts sum exactly to the total
  const w = sw.map((x) => Math.max(0.02, x * (1 + 0.12 * gauss())));
  const ws = w.reduce((a, b) => a + b, 0);
  const sec = w.map((x) => Math.floor((x / ws) * total));
  sec[5] += total - sec.reduce((a, b) => a + b, 0);
  days.push([d.toISOString().slice(0, 10), vals, sec]);
}

const data = {
  meta: {
    note: 'Data contoh (sintetis), bukan data asli.',
    source: 'Sintetis. Struktur disiapkan untuk diganti dengan data dari map.awanpintar.id',
    updated: days[N - 1][0],
  },
  types, sectors,
  // days: [tanggal, [jumlah per jenis serangan], [jumlah per sektor]]; urut dari lama ke baru
  days,
};

const tpl = fs.readFileSync(path.join(dir, 'template.html'), 'utf8');
const json = JSON.stringify(data).replace(/<\//g, '<\\/');
fs.writeFileSync(path.join(dir, 'dashboard.html'), tpl.replace('%%DATA%%', json));
console.log('ok', days.length, 'hari; hari terakhir', days[N - 1]);
